import * as readline from "readline";

const TOKEN_URL = "https://api.cakemail.dev/token";

function prompt(question: string, hidden = false): Promise<string> {
  return new Promise((resolve) => {
    const rl = readline.createInterface({
      input: process.stdin,
      output: process.stdout,
    });

    if (hidden) {
      // Suppress echo for password input
      const stdout = process.stdout;
      rl.question(question, (answer) => {
        rl.close();
        stdout.write("\n");
        resolve(answer);
      });
      // Hide typed characters
      (rl as unknown as { output: NodeJS.WritableStream }).output = process.stdout;
      process.stdin.on("keypress", () => {
        const len = (rl as unknown as { line: string }).line.length;
        readline.moveCursor(process.stdout, -len, 0);
        readline.clearLine(process.stdout, 1);
      });
    } else {
      rl.question(question, (answer) => {
        rl.close();
        resolve(answer);
      });
    }
  });
}

async function main() {
  console.log("Cakemail Token Refresh");
  console.log("======================\n");

  const username = await prompt("Cakemail username (email): ");
  const password = await prompt("Cakemail password: ");

  console.log("\nRequesting token...");

  const body = new URLSearchParams({
    grant_type: "password",
    username,
    password,
  });

  const res = await fetch(TOKEN_URL, {
    method: "POST",
    body,
  });

  if (!res.ok) {
    const text = await res.text();
    console.error(`\nError ${res.status}: ${text}`);
    process.exit(1);
  }

  const data = (await res.json()) as {
    access_token: string;
    refresh_token: string;
    token_type: string;
    expires_in: number;
  };

  console.log("\nSuccess!\n");

  console.log("Update the root `.env` (at the repo root, shared with the Astro site) with:\n");
  console.log(`CAKEMAIL_REFRESH_TOKEN='${data.refresh_token}'`);

  console.log(
    `\nAccess token expires in ${Math.round(data.expires_in / 60)} minutes.`,
  );
  console.log(
    "The refresh token is long-lived — replace it when it expires.",
  );
}

main();

